const fail = (m) => { throw new ParseError(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

const table = () => ({ t: 'table', map: new Map(), header: false })

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let curPath = []
  for (let i = 0; i < lines.length; i++) {
    try {
      const r = parseLine(lines[i], root, cur, curPath)
      if (r) { cur = r.cur; curPath = r.path }
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${i + 1}: ${e.message}`
      throw e
    }
  }
  return root
}

function parseLine(s, root, cur, curPath) {
  let p = 0
  const skip = () => { while (isWs(s[p])) p++ }
  const atEnd = () => p >= s.length || s[p] === '#' || s[p] === ';'
  skip()
  if (atEnd()) return null

  const parseString = () => {
    const q = s[p++]
    let out = ''
    if (q === "'") {
      const e = s.indexOf("'", p)
      if (e < 0) fail('unterminated string')
      out = s.slice(p, e)
      p = e + 1
      return out
    }
    for (;;) {
      if (p >= s.length) fail('unterminated string')
      const c = s[p++]
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (p >= s.length) fail('unterminated string')
      const d = String.fromCodePoint(s.codePointAt(p))
      p += d.length
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, d)) out += simple[d]
      else if (d === 'u') {
        const h = s.slice(p, p + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        p += 4
      } else fail(`invalid escape \\${d}`)
    }
  }

  const parseName = () => {
    const c = s[p]
    if (c === '"' || c === "'") return parseString()
    const st = p
    while (isNameChar(s[p])) p++
    if (p === st) fail('expected a name')
    return s.slice(st, p)
  }

  const parseDotted = () => {
    const parts = [parseName()]
    for (;;) {
      const save = p
      skip()
      if (s[p] === '.') {
        p++
        skip()
        parts.push(parseName())
      } else { p = save; break }
    }
    return parts
  }

  // Walk intermediate names; returns the table holding the last name.
  const walk = (start, base, parts) => {
    let t = start
    for (let i = 0; i < parts.length; i++) {
      const n = t.map.get(parts[i])
      if (n === undefined) {
        const nt = table()
        t.map.set(parts[i], nt)
        t = nt
      } else if (n.t === 'table') t = n
      else if (n.t === 'array' && n.aot) t = n.items[n.items.length - 1]
      else fail(`${[...base, ...parts.slice(0, i + 1)].join('.')} is not a table`)
    }
    return t
  }

  const assign = (start, base, parts, value) => {
    const t = walk(start, base, parts.slice(0, -1))
    const last = parts[parts.length - 1]
    if (t.map.has(last)) fail(`key ${[...base, ...parts].join('.')} is defined twice`)
    t.map.set(last, value)
  }

  const parseValue = () => {
    skip()
    const c = s[p]
    if (atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: parseString() }
    if (c === '[') {
      p++
      const items = []
      for (;;) {
        skip()
        if (atEnd()) fail('unterminated array')
        if (s[p] === ']') { p++; break }
        items.push(parseValue())
        skip()
        if (s[p] === ',') { p++; continue }
        if (s[p] === ']') { p++; break }
        fail('unterminated array')
      }
      return { t: 'array', items, aot: false }
    }
    if (c === '{') {
      p++
      const tb = table()
      skip()
      if (atEnd()) fail('unterminated inline table')
      if (s[p] === '}') { p++; return tb }
