    const aot = s[p] === '['
    if (aot) p++
    skip()
    const parts = parseDotted()
    skip()
    if (s[p] !== ']') fail('unterminated table header')
    p++
    if (aot) {
      if (s[p] !== ']') fail('unterminated table header')
      p++
    }
    skip()
    if (!atEnd()) fail('trailing text after a table header')
    const parent = walk(root, [], parts.slice(0, -1))
    const last = parts[parts.length - 1]
    const full = parts.join('.')
    const n = parent.map.get(last)
    if (aot) {
      const fresh = table()
      if (n === undefined) parent.map.set(last, { t: 'array', items: [fresh], aot: true })
      else if (n.t === 'array' && n.aot) n.items.push(fresh)
      else fail(`${full} is not an array of tables`)
      return { cur: fresh, path: fixPath(parts) }
    }
    if (n === undefined) {
      const nt = table()
      nt.header = true
      parent.map.set(last, nt)
      return { cur: nt, path: parts }
    }
    if (n.t !== 'table') fail(`${full} is not a table`)
    if (n.header) fail(`table ${full} is defined twice`)
    n.header = true
    return { cur: n, path: parts }
  }

